by_assignee_stats.map:
function (doc) {
  if(doc.type == 'issue' && doc.confirmed) {
    let assignee = 0;
    if (doc.assignee) {
      assignee = doc.assignee.id;
    }
    emit(assignee, 1);
  }
}

group_by_assignee.map:
function (doc) {
  if(doc.type == 'issue' && doc.confirmed && doc.status.name != 'Closed' && doc.assignee && doc.category) {
    emit([doc.category.assigned_department, doc.assignee.id, doc.assignee.name]);
  }
}

filters.exclude_unrelated_issues:
function(doc, req) {
 if (doc.type !== 'issue') return true;
 var userId = parseInt(req.query.user_id);
 if (doc.assignee && doc.assignee.id === userId) return true;
 if (doc.reporter && doc.reporter.id === userId) return true;
 return false;
 }
